TP.register({id:"lp3-g5",lp:3,grade:"5",mode:"curriculum",checks:2,nextGrade:"6th grade",build(E){const F=E.F;const STORY_TITLE="The Weigh-Off";const STORY=["All summer, Rohan had watered one pumpkin vine behind the shed at the community garden. He pulled every weed. He even slid a board under the pumpkin so it would not rot on the damp soil. Now it was the day of the Maple Fork weigh-off, and his pumpkin sat in a long row with nineteen others.","Most of them were much bigger than his. One was so wide that four adults had to roll it onto the scale. Rohan stuffed his hands in his pockets and stared at the hay on the ground.","“Number fourteen,” called the judge. Two helpers lifted Rohan’s pumpkin onto the scale. The red numbers blinked and stopped at sixty-one pounds. A few people clapped politely. The winning pumpkin weighed more than four hundred pounds.","Rohan had already loaded his pumpkin into his wagon and started for the gate when the judge spoke again. “We have one more ribbon,” she said. “It goes to the best pumpkin grown by someone under twelve. Our youngest grower kept a log of every watering since May. Number fourteen, please come back.”","Rohan turned around so quickly that the wagon nearly tipped. He walked to the table, and the judge pinned a green ribbon to his jacket. On the way home, he held the ribbon in one hand and a packet of seeds for next year in the other."].join("\n\n");const WAGON_TITLE="Last Wagon of the Day";const WAGON="By late afternoon, the pumpkin patch was a sea of orange. Vines crawled across the dirt like green ropes, and Camila had to step high to keep from tripping. The sunflowers along the fence were tired guards, their heavy heads bowed after a long day in the sun. Camila had loaded pumpkins since lunch. The biggest one was a stubborn mule that refused to budge until two friends helped her push. At last the wagon was full. The tractor coughed twice, and the wagon rolled toward the barn as slowly as a snail on a cold morning. Camila climbed onto a hay bale at the back. Her arms felt like wet rope. The sky was a peach-colored quilt, and the first cool breeze of the evening slid over the field like a sigh. She had never been so tired, and she had never felt so proud.";const SOURCES=[["Source 1","<i>Giants of the Garden</i>, a book by Rosa Castillo","Giant pumpkins start with seeds saved from other giant pumpkins. When small pumpkins form on the vine, the grower picks the best one and cuts off the rest. Now the vine sends all of its food and water to a single fruit."],["Source 2","“A Day with a Champion Grower,” a magazine article by Ben Hollis","In the middle of summer, a giant pumpkin can gain more than 30 pounds in one day. Growers water the vine every day. They also shade the pumpkin with a sheet so the hot sun does not crack its skin."]];const WORD_STACK=["circumference","horticulture","unpredictable","measurement","cultivation","irresistible"];const RULES="Here is how a weigh-off works. Growers bring their pumpkins to the scale on a wagon or a pallet. A judge checks that the stem is still attached and that the skin has no holes or soft spots. Helpers lift each pumpkin onto a flat scale with a crane or a sling. The scale shows the weight in pounds, and the judge calls the number out loud. The pumpkins are weighed in the order the growers signed up, not in order of size. The heaviest pumpkin wins the top prize, and most weigh-offs hand out smaller ribbons too.";const REPORT_FACTS=["Bees carry pollen from flower to flower.","The seed sprouts in about a week.","The green pumpkin turns orange, and its stem gets hard.","Big yellow flowers open on the vine.","A small green pumpkin starts to grow under a flower.","Seeds are planted in late spring, when the soil is warm."];function group(inner,label){return`<div style="text-align:center"><div style="display:flex;gap:12px;flex-wrap:wrap;justify-content:center;align-items:center">${inner}</div><p class="fig-label" style="margin:4px 0 0">${label}</p></div>`}function pumpkinAt(x,y,r){return`<rect x="${x-r*.12}" y="${y-r*1.02}" width="${r*.24}" height="${r*.34}" rx="2" fill="var(--sea)" stroke="var(--ink)" stroke-width="1.5"/><ellipse cx="${x}" cy="${y}" rx="${r}" ry="${r*.8}" fill="var(--gold)" stroke="var(--gold-ink)" stroke-width="2.5"/><ellipse cx="${x}" cy="${y}" rx="${r*.55}" ry="${r*.8}" fill="none" stroke="var(--gold-ink)" stroke-width="1.5"/><line x1="${x}" y1="${y-r*.8}" x2="${x}" y2="${y+r*.8}" stroke="var(--gold-ink)" stroke-width="1.5"/>`}function pumpkins(n,perRow){const cell=62,rows=Math.ceil(n/perRow),W=perRow*cell+8,H=rows*cell+10;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="${n} pumpkins">`;for(let k=0;k<n;k++){const c=k%perRow,r=Math.floor(k/perRow);s+=pumpkinAt(4+c*cell+cell/2,10+r*cell+cell/2,cell*.4)}return s+"</svg>"}const onePumpkin=size=>`<svg viewBox="0 0 60 56" width="${size}" role="img" aria-label="A pumpkin">${pumpkinAt(30,31,24)}</svg>`;function loaf(){return`<svg viewBox="0 0 130 70" width="130" role="img" aria-label="One loaf of pumpkin bread"><path d="M8 62 V30 Q8 8 34 8 H96 Q122 8 122 30 V62 Z" fill="var(--gold)" stroke="var(--gold-ink)" stroke-width="4" stroke-linejoin="round"/><line x1="8" y1="34" x2="122" y2="34" stroke="var(--gold-ink)" stroke-width="2" stroke-dasharray="6 6"/></svg>`}const person=`<span style="display:inline-block;margin-right:6px">${F.icon("face",56)||"👤"}</span>`;const people=n=>`<span style="font-size:3rem;letter-spacing:6px" role="img" aria-label="${n} friends">${person.repeat(n)}</span>`;function box(){return`<div style="border:4px solid var(--gold-ink);border-radius:14px;padding:8px 14px;background:var(--surface);display:flex;gap:6px;align-items:center">${onePumpkin(54)}${onePumpkin(54)}${onePumpkin(54)}<span style="font-size:2.6rem" aria-hidden="true">${F.icon("corn",52)}<span style="display:inline-block;margin-left:6px">${F.icon("corn",52)}</span></span></div>`}function pvFig(heads,digits){const th=h=>`<th style="padding:6px 10px;font-size:1rem">${h}</th>`;const td=d=>`<td style="padding:4px 10px;font-size:2.4rem;font-weight:700;text-align:center;font-family:var(--font-display)">${d}</td>`;return`<table class="chart" style="margin:0 auto"><tr>${heads.map(th).join("")}</tr><tr>${digits.map(td).join("")}</tr></table>`}function tag(name,val){return`<div style="border:3px solid var(--gold-ink);border-radius:16px;padding:8px 22px;background:var(--surface);text-align:center;min-width:150px">${onePumpkin(52)}<div class="fig-label" style="margin:0">${name}</div><div style="font-size:2.2rem;font-weight:700;font-family:var(--font-display);color:var(--ink)">${val}</div></div>`}function bedFig(){const ox=110,oy=40,S=240,cw=S/4,rh=S/3;let s=`<svg viewBox="0 0 440 320" width="440" role="img" aria-label="A square garden cut into 3 rows and 4 columns. A part 3 columns long and 2 rows wide is shaded.">`;for(let r=0;r<3;r++)for(let c=0;c<4;c++)s+=`<rect x="${ox+c*cw}" y="${oy+r*rh}" width="${cw}" height="${rh}" fill="${r<2&&c<3?"var(--gold)":"var(--surface)"}" stroke="var(--ink)" stroke-width="2"/>`;const t=(x,y,txt,a)=>`<text x="${x}" y="${y}" text-anchor="${a||"middle"}" font-size="18" font-weight="700" fill="var(--ink)">${txt}</text>`;s+=`<line x1="${ox}" y1="${oy-10}" x2="${ox+3*cw}" y2="${oy-10}" stroke="var(--ink)" stroke-width="2"/>`+t(ox+1.5*cw,oy-18,"3/4 yard");s+=`<line x1="${ox-10}" y1="${oy}" x2="${ox-10}" y2="${oy+2*rh}" stroke="var(--ink)" stroke-width="2"/>`+t(ox-18,oy+rh+6,"2/3 yard","end");s+=t(ox+S/2,oy+S+26,"1 yard")+t(ox+S+12,oy+S/2+6,"1 yard","start");return s+"</svg>"}const checklist=items=>`<ul class="qlist" style="margin-top:14px">${items.map(x=>`<li>${x}</li>`).join("")}</ul>`;const pills=items=>`<div class="row center" style="margin-top:18px;gap:14px;flex-wrap:wrap">${items.map(x=>`<span class="pill" style="font-size:1.25rem">${x}</span>`).join("")}</div>`;const factBox=(title,items)=>`<div style="border:3px dashed var(--line);border-radius:16px;padding:8px 18px;margin:14px auto 0;max-width:820px;background:var(--surface)"><p class="fig-label" style="margin:0 0 4px">${title}</p><ul style="margin:0;padding-left:22px;font-size:1.2rem;line-height:1.5">${items.map(x=>`<li>${x}</li>`).join("")}</ul></div>`;const factCards=items=>`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px">${items.map(x=>`<div style="border:3px solid var(--line);border-radius:14px;padding:10px 14px;background:var(--surface);font-size:1.25rem;line-height:1.35">${x}</div>`).join("")}</div>`;const sourcesHtml=()=>`<div class="texts">${SOURCES.map(t=>`<article><h3>${t[0]}</h3><p class="small" style="margin:0 0 6px">${t[1]}</p><p>${t[2]}</p></article>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const STOPS=[{id:1,title:"Weigh-Off Warm-Up",short:"Warm-Up Read",parts:[{std:["RF.5.4"],kind:"read",n:0,label:"words read correctly",dur:110,dir:"Read the story out loud at your normal speed. Use your best reading voice.",desc:"a grade-level story read aloud",html:()=>F.passage(STORY,STORY_TITLE),key:["__WC__ words, not counting the title. Time 1 minute, mark the last word read, and count errors on your own copy. Let the student finish the story.","Fall grade 5 benchmark: about 121 words correct per minute (50th percentile).","Note pace, phrasing, and expression. Listen for a change in voice when the judge speaks, and for self-corrections that show the student is reading for meaning."]}]},{id:2,title:"Pumpkin Bread Shares",short:"Bread Shares",parts:[{std:["5.NF.B.3"],dur:140,dir:"Solve on your paper. Then tell your teacher your answers.",desc:"fractions as division, with sharing problems that have fraction and mixed number answers",fig:()=>`<div class="figure" style="gap:40px">${group(`<div style="display:grid;grid-template-columns:repeat(2,auto);gap:8px">${loaf()+loaf()+loaf()+loaf()}</div>`,"4 loaves of pumpkin bread")}${group(`<div style="max-width:240px">${people(6)}</div>`,"6 friends")}</div>`,qs:["Look at the picture. 4 loaves of pumpkin bread are shared equally by 6 friends. How much bread does each friend get?","Write 11 ÷ 4 as a fraction and as a mixed number.","15 pounds of pumpkin seeds are poured equally into 8 bags. How many pounds are in each bag? Between what two whole numbers is your answer?","Would you rather share 5 gallons of cider equally among 4 people, or 7 gallons of cider equally among 6 people? Tell the size of one share for each choice.","3 ÷ 5 = 3/5. So what is 5 × 3/5? Tell how you know without working it out on paper."],key:["4/6 of a loaf, which is the same as 2/3 of a loaf. Or: 4 ÷ 6 written as a division counts equally. Partial: 6/4 reverses the share and does not count. (5.NF.B.3)","11/4 and 2 3/4. Partial: one of the two forms given is approaching. (5.NF.B.3)","15/8 pounds, which is 1 7/8 pounds. It is between 1 and 2. Partial: 15/8 right with no pair of whole numbers named is approaching. (5.NF.B.3)","5 ÷ 4 = 5/4, or 1 1/4 gallons each. 7 ÷ 6 = 7/6, or 1 1/6 gallons each. The first choice gives a bigger share because 1/4 is more than 1/6. Both share sizes are needed. Partial: the right choice with only one share size given is approaching. (5.NF.B.3)","3. Each share is 3/5, and 5 equal shares put back together make the 3 wholes that were divided. Also correct: multiplying by 5 undoes dividing by 5. Partial: 3 given with no reason is approaching. (5.NF.B.3)"]}]},{id:3,title:"The Weigh-Off",short:"Weigh-Off",parts:[{std:["RL.5.1"],dur:150,dir:"Read the story. Then answer out loud. Read me the exact words from the story that prove each answer.",desc:"quoting the story accurately to tell what it says and to back up inferences",html:()=>F.passage(STORY,STORY_TITLE,true),qs:["What did Rohan do to take care of his pumpkin? Read me two sentences from the story that tell you.","How did Rohan feel when he saw the other pumpkins? The story does not say it in one word. Read me the sentence that proves your answer.","Did Rohan expect to win a ribbon? Read me the words that prove it.","Will Rohan grow a pumpkin again? Read me the words that prove it."],key:["Reads any two: “All summer, Rohan had watered one pumpkin vine behind the shed at the community garden,” “He pulled every weed,” or “He even slid a board under the pumpkin so it would not rot on the damp soil.” For every answer, the student should read the words as written, not retell them loosely. (RL.5.1, explicit)","Discouraged, embarrassed, or let down. Quotes “Rohan stuffed his hands in his pockets and stared at the hay on the ground.” (RL.5.1, inference)","No. Quotes “Rohan had already loaded his pumpkin into his wagon and started for the gate when the judge spoke again.” (RL.5.1, inference)","Yes. Quotes “a packet of seeds for next year.” (RL.5.1, inference)"]}]},{id:4,title:"Scarecrow’s Puzzles",short:"Puzzles",parts:[{std:["5.OA.A.1"],dur:140,dir:"Solve each one on your paper. Then tell your teacher your answers.",desc:"using and evaluating expressions with parentheses, brackets, and braces",qs:["(9 + 3) × 4 = ?","6 × [15 − (4 + 5)] = ?","{2 × [9 + (8 ÷ 4)]} − 7 = ?","Add parentheses to make this true: 4 × 6 + 2 − 5 = 27","Look at the picture. A farmer packs 6 boxes. Each box holds 3 pumpkins and 2 ears of corn. Which expression gives the total number of things in the boxes: 6 × 3 + 2 or 6 × (3 + 2)? Tell how you know."],fig2:()=>`<div class="figure">${group(box(),"One box")}</div>`,key:["48. Add first: 12 × 4. Partial: 21 comes from multiplying before adding and does not count. (5.OA.A.1)","36. Work from the inside out: 4 + 5 = 9, then 15 − 9 = 6, then 6 × 6. Partial: 6 found by stopping at 15 − 9 is approaching. (5.OA.A.1)","15. 8 ÷ 4 = 2, then 9 + 2 = 11, then 2 × 11 = 22, then 22 − 7. Partial: 22 found by stopping before the subtraction is approaching. (5.OA.A.1)","4 × (6 + 2) − 5 = 27. Check: 4 × 8 = 32, and 32 − 5 = 27. Partial: parentheses placed anywhere that does not give 27 does not count. (5.OA.A.1)","6 × (3 + 2), which is 30. The parentheses add the 5 things in one box first, and then that is multiplied by 6 boxes. 6 × 3 + 2 is only 20. Partial: naming the right expression with no reason is approaching. (5.OA.A.1)"]}]},{id:5,title:"Hay Bale Signs",short:"Sign Fixer",parts:[{std:["L.5.1"],dur:70,dir:"Each sign has one mistake. Say the whole sentence the right way.",desc:"fixing spoken grammar mistakes (verb tense shifts, perfect tenses, paired conjunctions)",qs:["Last week we planted the seeds, water them, and waited.","Since June, the vines grown ten feet.","Neither the wagon or the tractor would start.","When we reached the patch, the sun already set.","Not only did the pumpkins grow big, and they also turned bright orange."],key:["Last week we planted the seeds, watered them, and waited. (L.5.1, fixing a shift in verb tense)","Since June, the vines have grown ten feet. (L.5.1, present perfect tense)","Neither the wagon nor the tractor would start. (L.5.1, correlative conjunctions neither/nor)","When we reached the patch, the sun had already set. (L.5.1, past perfect tense)","Not only did the pumpkins grow big, but they also turned bright orange. (L.5.1, correlative conjunctions not only/but also)"]}]},{id:6,title:"Patch Parts",parts:[{std:["5.NF.B.4"],dur:100,dir:"Look at the picture. Solve on your paper. Then tell your teacher your answers.",desc:"multiplying a whole number by a fraction",fig:()=>`<div class="figure">${group(pumpkins(12,6),"12 pumpkins on the wagon")}</div>`,qs:["1/4 of the 12 pumpkins will be sold today. How many pumpkins is that?","3/4 × 12 = ?","2/3 × 5 = ?","Tell how you know: Why is 3/4 of 8 equal to 6? Use words or a quick drawing."],key:["3 pumpkins. 12 split into 4 equal groups is 3 in each group. Or: 1/4 × 12 = 12/4 = 3. (5.NF.B.4)","9. Or: 12 ÷ 4 = 3, then 3 × 3 = 9. (5.NF.B.4)","10/3, which is 3 1/3. Or: 1/3 of 5 is 5/3, and two of those is 10/3. (5.NF.B.4)","Split 8 into 4 equal groups of 2. Three of those groups make 6. Also correct: 3 × 8 = 24, and 24 ÷ 4 = 6. Partial: 6 given with no words and no drawing is approaching. (5.NF.B.4)"]}]},{id:7,title:"Last Wagon of the Day",short:"Last Wagon",parts:[{std:["RL.5.4"],dur:110,dir:"Read the story. Then answer out loud.",desc:"explaining similes, metaphors, and words as they are used in a story",html:()=>F.passage(WAGON,WAGON_TITLE,true),qs:["“The pumpkin patch was a sea of orange.” What does this tell you about the patch? Is it a simile or a metaphor? How do you know?","“The sunflowers along the fence were tired guards.” How are the sunflowers like tired guards?","“The biggest one was a stubborn mule.” What is being compared to a mule? What does the author mean?","Find the simile that tells how the wagon moved. What does it mean?","What does the word budge mean in this story? Which words help you know?"],key:["There were so many pumpkins that orange spread out in every direction, the way water does in a sea. It is a metaphor because it says the patch was a sea and does not use like or as. (RL.5.4, metaphor)","They stand tall in a row along the fence the way guards stand watch, and their heavy heads are bowed as if they are worn out. (RL.5.4, metaphor)","The biggest pumpkin. It was so heavy that it would not move, the way a stubborn mule will not move. (RL.5.4, metaphor)","“As slowly as a snail on a cold morning.” The full wagon moved very slowly. (RL.5.4, simile)","To move, even a little. Clues: it “refused to” do it “until two friends helped her push.” (RL.5.4, meaning of a word as used in the text)"]}]},{id:8,title:"Place Value Patch",short:"Value Patch",parts:[{std:["5.NBT.A.1"],dur:115,dir:"Look at the place value chart. Answer out loud. For number 4, write your number on your paper and hold it up.",desc:"using the 10 times and 1/10 pattern between decimal places",fig:()=>`<div class="figure">${group(pvFig(["Ones",".","Tenths","Hundredths","Thousandths"],["2",".","2","2","2"]),"A mini pumpkin on the scale, in pounds")}</div>`,qs:["Look at the chart. The 2 in the tenths place is worth how many times as much as the 2 in the hundredths place?","The 2 in the thousandths place is worth what fraction of the 2 in the hundredths place?","Fill in both blanks: 0.6 is 10 times as much as ____. 0.006 is 1/10 of ____.","Write a number that has a 3 worth 10 times as much as the 3 in 1.63.","Spot the mistake. Omar says, “The 5 in 0.5 is worth 1/10 of the 5 in 0.05, because 0.05 has more digits.” Is Omar right? Tell how you know."],key:["10 times as much. 0.2 is 10 × 0.02. Partial: naming the two values with no comparison is approaching. (5.NBT.A.1)","1/10. 0.002 is 1/10 of 0.02. Partial: 10 times as much reverses the comparison and does not count. (5.NBT.A.1)","0.06 for both blanks. Partial: one of the two blanks right is approaching. (5.NBT.A.1)","The 3 in 1.63 is worth 0.03, and 10 times 0.03 is 0.3. Any number with a 3 in the tenths place is correct, such as 0.3, 5.31, or 12.3. Partial: a number with the 3 in the hundredths place is approaching. (5.NBT.A.1)","No. He has it backward. 0.5 is 5 tenths and 0.05 is 5 hundredths, so the 5 in 0.5 is worth 10 times as much. The 5 in 0.05 is worth 1/10 of the 5 in 0.5. Partial: saying no with no reason from the places is approaching. (5.NBT.A.1)"]}]},{id:9,title:"Harvest Writer",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Who should get the top ribbon?"},std:["W.5.1"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"an opinion writing piece",html:()=>`<p class="big">At the pumpkin weigh-off, should the top ribbon go to the heaviest pumpkin or to the best-looking pumpkin? Write your opinion. Give at least two reasons. Write 5 to 8 sentences.</p>${checklist(["Say your opinion","Give at least two reasons","Back up each reason with a fact or an example","Use linking words: because, for example, also","End with a closing sentence"])}`,key:["Introduces the topic and states an opinion clearly (W.5.1)","Gives reasons in an order that makes sense (W.5.1)","Supports the reasons with facts, details, or examples (W.5.1)","Links the opinion and reasons with words and phrases such as because, for example, also, in addition (W.5.1)","Ends with a concluding sentence that goes with the opinion (W.5.1)"]},{alt:{group:"write",key:"facts",label:"Explain",icon:"📘",hint:"Teach a reader about pumpkins"},std:["W.5.2"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"an informative writing piece",html:()=>`<p class="big">Write to teach a reader about pumpkins. Use at least three facts from the fact box. Put them in an order that makes sense. Write 5 to 8 sentences.</p>${factBox("Fact box: pumpkins",["A pumpkin is a fruit because it grows from a flower and holds seeds.","A pumpkin is about 90 percent water.","One pumpkin vine can grow more than 20 feet long.","A pumpkin needs about 100 days to grow from a seed to harvest size.","Pumpkins are grown on every continent except Antarctica."])}${checklist(["Start by naming your topic","Put facts that go together next to each other","Use linking words: also, another, for example, because","End with a closing sentence"])}`,key:["Introduces the topic clearly (W.5.2)","Groups related information in an order that makes sense (W.5.2)","Develops the topic with at least three facts or details from the fact box, written in the student’s own sentences (W.5.2)","Links ideas with words and phrases such as also, another, for example, because, in contrast (W.5.2)","Ends with a concluding sentence (W.5.2)"]},{alt:{group:"write",key:"story",label:"Story",icon:"✨",hint:"Lost in the corn maze"},std:["W.5.3"],n:5,label:"checks met",dur:300,dir:WRITE_DIR,desc:"a narrative writing piece",html:()=>`<p class="big">You and a friend walk into the corn maze. After three turns, every path looks the same. Then you notice a clue that might help you find the way out. Write the story of what happens. It can be real or made up. Write 5 to 8 sentences.</p>${pills(["At first","Then","After that","Finally"])}${checklist(["Tell who is in the story and where it happens","Tell the events in order","Show what someone says, thinks, or feels","Use details a reader can see, hear, or feel","Give your story an ending"])}`,key:["Orients the reader: sets up the situation and introduces the narrator or characters (W.5.3)","Events unfold in a clear order, with transition words such as at first, later, after that, finally (W.5.3)","Uses dialogue or description to show what happens and how the characters respond (W.5.3)","Uses concrete words and sensory details (W.5.3)","Has an ending that follows from the events (W.5.3)"]}]},{id:10,title:"Sunflower Bed",parts:[{std:["5.NF.B.4"],dur:125,dir:"Solve on your paper. Then tell your teacher your answers.",desc:"multiplying a fraction by a fraction, with an area model",qs:["1/3 × 1/2 = ?","2/5 × 3/4 = ?","5/6 × 3 = ?","Look at the picture. The big square is 1 square yard of garden. The shaded sunflower bed is 3/4 yard long and 2/3 yard wide. Write a multiplication equation for the area of the sunflower bed.","Spot the mistake. Cole says, “2/3 × 4 = 8/12.” What did he do wrong? What is the right answer?"],fig2:()=>`<div class="figure">${bedFig()}</div>`,key:["1/6. Or: an area model, half of a third of the square. (5.NF.B.4)","6/20, which is the same as 3/10. Or: a 5 by 4 area model with 6 of the 20 squares shaded. (5.NF.B.4)","15/6, which is the same as 2 3/6 or 2 1/2. Or: 5/6 + 5/6 + 5/6 = 15/6. (5.NF.B.4)","3/4 × 2/3 = 6/12, which is the same as 1/2 square yard. 6 of the 12 equal parts are shaded. Partial: the equation right with no area given is approaching. (5.NF.B.4)","He multiplied the top and the bottom by 4. That only makes another name for 2/3. The right answer is 8/3, or 2 2/3, because 4 is 4/1. Partial: naming the mistake with no right answer given is approaching. (5.NF.B.4)"]}]},{id:11,title:"Corn Maze Words",short:"Maze Words",parts:[{std:["L.5.1"],dur:70,dir:"Every word has a job. Answer out loud.",desc:"spoken grammar items (interjections, prepositions, conjunctions, future perfect, both/and)",qs:["“Whew, we finally found the way out of the corn maze!” Which word is the interjection? What does it show?","“The wagon rolled between the rows and through the gate.” Find two prepositions. What do they tell you?","“The pumpkins will keep growing ____ the first frost comes.” Which conjunction fits best: until, but, or so? Tell why.","Say the sentence with the right form of the verb sell: “By the end of October, the farmers ____ every pumpkin in the patch.”","Make one sentence. Use the word pair both/and: “The hay bales are heavy. The hay bales are scratchy.”"],key:["Whew. It shows a feeling: relief. (L.5.1, interjection)","between and through. They tell where the wagon went. (L.5.1, prepositions)","until. It joins the two parts of the sentence and tells when the growing stops. (L.5.1, conjunction)","By the end of October, the farmers will have sold every pumpkin in the patch. (L.5.1, future perfect tense)","The hay bales are both heavy and scratchy. (L.5.1, correlative conjunctions both/and)"]}]},{id:12,title:"Weigh-Off Scale",short:"Scale",parts:[{std:["5.NBT.A.3"],dur:125,dir:"Say number 1 out loud. Write the rest on your paper and hold it up.",desc:"reading, writing, comparing, and ordering decimals to thousandths",fig:()=>`<div class="figure" style="gap:24px">${tag("Pumpkin A","12.48 kg")}${tag("Pumpkin B","12.5 kg")}${tag("Pumpkin C","12.409 kg")}</div>`,qs:["Read this number out loud: 30.045","Write this number: two hundred six and nine hundredths.","Write 7.036 in expanded form.","Put the three pumpkins in order from heaviest to lightest. Tell how you know which one is heaviest.","Write a decimal that is greater than 0.4 and less than 0.41."],key:["Thirty and forty-five thousandths. Partial: thirty point zero four five is approaching, since the place value name is what is asked. (5.NBT.A.3, read)","206.09. Partial: 206.9 puts the 9 in the tenths place and does not count. (5.NBT.A.3, write)","7 + 0.03 + 0.006, or 7 × 1 + 3 × (1/100) + 6 × (1/1000). There are no tenths. Partial: writing a tenths term is approaching, since there are none. (5.NBT.A.3, expanded form)","Pumpkin B (12.5 kg), then Pumpkin A (12.48 kg), then Pumpkin C (12.409 kg). All three have 12 ones. B has 5 tenths and the others have 4 tenths, so B is heaviest. Or: line the three up as thousandths, 12.500, 12.480, 12.409. Partial: two of the three in order is approaching. (5.NBT.A.3, compare)","Any decimal between them, such as 0.401, 0.405, or 0.409. The student needs the thousandths place. Partial: 0.4 or 0.41 itself is approaching, since the decimal has to sit between them. (5.NBT.A.3, compare)"]}]},{id:13,title:"Giant Pumpkin Notes",short:"Giant Notes",parts:[{std:["W.5.8"],n:4,label:"checks met",dur:145,dir:"Read the two sources. Write your notes on your paper and hold it up.",desc:"notes in the student’s own words from two sources, a spoken summary, and a list of sources",html:()=>`<p class="big" style="font-size:1.5rem">Question: How do growers get a pumpkin to grow so big?</p>${sourcesHtml()}<ol class="qlist"><li>Write 3 short notes that answer the question. Use your own words. A note is a few words, not a whole sentence. Use both sources.</li><li>Under your notes, list your sources. Write the title and the author of each one.</li><li>Now look only at your notes. Answer the question out loud in one or two sentences.</li></ol>`,key:["Writes 3 notes that answer the question and uses both sources, such as: seeds from giant pumpkins, keep only the best pumpkin on the vine, all food and water go to one fruit, water every day, shade it with a sheet so the skin does not crack. (W.5.8, gathers relevant information)","Notes are short and in the student’s own words, not sentences copied from the sources. (W.5.8, paraphrases in notes)","Lists both sources by title and author: Giants of the Garden by Rosa Castillo and “A Day with a Champion Grower” by Ben Hollis. (W.5.8, list of sources)","Sums up the answer out loud from the notes, in the student’s own words, with correct facts. (W.5.8, summarizes in finished work)"]}]},{id:14,title:"Pumpkin Report",short:"Report",parts:[{std:["SL.5.4"],n:5,label:"checks met",dur:110,dir:"Plan for 1 minute. Then give your report out loud.",desc:"reporting on a topic out loud with facts in a logical order and clear speech",html:()=>`<p class="big">Give a short report, about 1 minute long, that teaches how a pumpkin grows. The fact cards are mixed up. Tell the facts in an order that makes sense, and add details of your own.</p>${factCards(REPORT_FACTS)}`,key:["Starts by telling what the report is about (SL.5.4, reports on a topic)","Tells the facts in an order that makes sense: seeds are planted, the seed sprouts, yellow flowers open, bees carry pollen, a small green pumpkin grows, it turns orange and the stem hardens (SL.5.4, sequences ideas logically)","Uses at least four of the facts and adds a descriptive detail or an explanation of the student’s own (SL.5.4, facts and details)","Ends with a closing sentence (SL.5.4)","Speaks clearly at a pace that is easy to follow (SL.5.4)"]}]},{id:15,title:"Weigh-Off Word Stack",short:"Word Stack",parts:[{std:["RF.5.3"],kind:"words",words:WORD_STACK,unit:"Word",n:6,dur:45,dir:"Read each word out loud. Break it into parts if it helps.",desc:"reading unfamiliar multisyllabic words using syllable patterns and word parts",key:["The words are circumference, horticulture, unpredictable, measurement, cultivation, irresistible. Count each word read correctly.","Watch for: the prefixes circum- and un-, the roots cultiv- and hort-, and the suffixes -ment, -ation, -able and -ible.","If a word stalls, say: Cover part of it. What part do you know? A word the student fixes alone still counts."]}]},{id:16,title:"How a Weigh-Off Works",short:"Listen",parts:[{std:["SL.5.2"],n:3,label:"checks met",dur:45,read:RULES,dir:"Listen while your teacher reads. The words are not on your screen. Then summarize out loud.",desc:"summarizing a text read aloud",html:()=>`<div class="figure">${onePumpkin(110)}</div><p class="big" style="text-align:center">Listen, then tell me the gist in two or three sentences.</p>`,key:["Read the text out loud once. Read it again only if the student asks.","Sums it up in two or three sentences and gets the main point: a weigh-off is an orderly check and weighing of each pumpkin, and the heaviest one wins. (SL.5.2)","Includes at least two key details, such as the judge checks the stem and the skin, helpers use a crane or a sling, pumpkins are weighed in sign-up order rather than by size, or smaller ribbons are given too. (SL.5.2)","Summarizes rather than retelling every line or adding an opinion of their own. (SL.5.2)"]}]},{id:17,title:"Two Giant Sources",short:"Sources",parts:[{std:["RI.5.1","RI.5.9"],n:3,dur:55,dir:"Read both sources. Then answer out loud. Quote the exact words when you are asked to.",desc:"quoting accurately from an informational text and using two texts on one topic together",html:()=>sourcesHtml(),key:["Ask: Why does the grower cut off all but one small pumpkin? Quote the exact words that tell you. (Reads: Now the vine sends all of its food and water to a single fruit.) (RI.5.1)","Ask: Source 2 says a giant pumpkin can gain more than 30 pounds in one day. What does Source 1 tell you that helps explain how that is possible? (All of the vine's food and water goes to one fruit instead of being split between several.) (RI.5.9)","Ask: Using both sources, name three things a grower does to get one huge pumpkin. (Any three: start with seeds saved from giant pumpkins, keep only the best small pumpkin and cut off the rest, water the vine every day, shade the pumpkin with a sheet so the skin does not crack.) (RI.5.9)"]}]},{id:18,title:"Watering Log Fractions",short:"Log Math",parts:[{std:["5.NF.A.1","5.NF.A.2"],n:3,dur:50,dir:"Solve on your paper and hold it up. Tell how you know.",desc:"adding and subtracting fractions with unlike denominators, and checking that an answer is reasonable",qs:["Rohan's log says he watered for 2/5 of an hour on Monday and 1/2 of an hour on Tuesday. How long did he water in all?","A tray of pumpkin bread was 3/4 full. The crew ate 1/3 of the tray. How much of the tray is left?","Without finishing the arithmetic, is 3/4 minus 1/3 closer to 0 or closer to 1? How can you tell?"],key:["9/10 of an hour. 2/5 = 4/10 and 1/2 = 5/10, so 4/10 + 5/10 = 9/10. Or: twentieths work too, 8/20 + 10/20 = 18/20 = 9/10. Partial: 3/7 comes from adding across and does not count. (5.NF.A.1)","5/12 of the tray. 3/4 = 9/12 and 1/3 = 4/12, so 9/12 - 4/12 = 5/12. Partial: 2/1 comes from subtracting across and does not count. (5.NF.A.2)","Closer to 0. 3/4 is a little more than 1/2 and 1/3 is a little less than 1/2, so the difference is small. Using benchmarks like 1/2 is the point here, not the exact answer. Partial: naming closer to 0 with no benchmark reason is approaching. (5.NF.A.2)"]}]},{id:19,title:"Crate Volume",short:"Volume",parts:[{std:["5.MD.C.3","5.MD.C.5"],n:3,dur:45,dir:"Look at the crate. Answer out loud.",desc:"counting unit cubes to measure volume and using the volume formula",fig:()=>F.row(F.prism(4,3,2,{unit:34})),qs:["A cube that is 1 unit on every edge is a unit cube. It has a volume of 1 cubic unit. How many unit cubes fill this crate?","Find the same volume without counting cube by cube. What did you multiply?","A seed crate is 6 feet long, 2 feet wide, and 3 feet high. What is its volume?"],key:["24 unit cubes, so the volume is 24 cubic units. Counting a layer of 12 and doubling it also counts. Partial: 24 with no unit named is approaching. (5.MD.C.3)","24 cubic units, from 4 x 3 x 2, which is length times width times height. Finding the area of the base, 12, and multiplying by the height, 2, counts too. Partial: the right total with no multiplication named is approaching. (5.MD.C.5)","36 cubic feet, from 6 x 2 x 3. The unit has to be cubic feet. Or: 6 × 2 = 12 for the base, then 12 × 3. (5.MD.C.5)"]}]},{id:20,title:"Map of the Patch",short:"Map",parts:[{std:["5.G.A.1"],n:3,dur:45,dir:"Look at the map grid. Answer out loud.",desc:"reading ordered pairs on a coordinate grid and naming the axes and the origin",fig:()=>F.row(F.coordGrid({min:0,max:8,size:330,points:[[3,5,"Barn"],[6,2,"Gate"]]})),qs:["What is the ordered pair for the barn?","In an ordered pair, what does the first number tell you? what does the second number tell you?","The ticket stand sits at (0, 0). What is that point called, and where is it on the grid?"],key:["(3, 5). Partial: (5, 3) reverses the pair and is approaching. (5.G.A.1)","The first number tells how far to travel from the start along the horizontal axis, the x-axis. The second tells how far to travel along the vertical axis, the y-axis. Saying across first, then up counts. Partial: one of the two numbers explained is approaching. (5.G.A.1)","The origin. It is the corner where the two axes cross, at the bottom left of this grid. Partial: naming the origin with no account of where it sits is approaching. (5.G.A.1)"]}]},{id:21,title:"What You Cannot See",short:"Tiny Bits",parts:[{std:["5-PS1-1"],n:3,dur:75,dir:"Answer out loud.",desc:"using a model of particles too small to be seen to explain what happens to matter",html:()=>`<p class="big">Pumpkin bread comes out of the oven at one end of the barn. Within a minute everyone at the far end can smell it, even people who never looked up.</p>
     <div class="figure">${F.icon("bread",84)}${F.icon("nose",84)}${F.icon("pumpkin",84)}</div>`,qs:["Nothing visible crossed the barn. Explain how the smell reached the far end.","A tight balloon left in the barn slowly goes soft over a week, even with no hole you can find. Use particles to explain it.","Why is it fair to call air matter, when you cannot see it, hold it, or taste it?"],key:["Particles of the substances that make the smell left the bread, spread out through the air, and travelled until enough of them reached each person's nose. They are far too small to see. (5-PS1-1)","The particles inside are small enough to slip between the particles of the rubber itself, a few at a time, so gas escapes without any hole big enough to find. (5-PS1-1)","Because it is made of particles that take up space and have weight. A sealed bag of air weighs more than the same bag emptied, and air can push things, such as filling a sail. (5-PS1-1)"]},{std:["5-PS1-3"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"identifying materials from measured properties rather than from appearance",html:()=>`<p class="big">Four fence posts were pulled out of the patch. All four are weathered grey and the same size.</p>
     <table class="bigTable"><tr><th>Post</th><th>Mass</th><th>Floats in water?</th><th>Warms up fast when one end is heated?</th><th>Dents with a hammer?</th></tr>
     <tr><td>A</td><td>1.4 kg</td><td>yes</td><td>no</td><td>yes, crushes</td></tr>
     <tr><td>B</td><td>2.6 kg</td><td>yes</td><td>no</td><td>no, splits</td></tr>
     <tr><td>C</td><td>5.9 kg</td><td>no</td><td>yes</td><td>no, rings</td></tr>
     <tr><td>D</td><td>1.1 kg</td><td>yes</td><td>no</td><td>no, springs back</td></tr></table>
     <p class="big">The four materials are soft pine, dense oak, steel, and plastic pipe.</p>`,qs:["Which post is the steel? Name two test results that show it.","Posts A and B both float and neither conducts heat well. Which is the dense oak, and which column decided it?","Post D is light, floats, and springs back. Which material is it, and which single result rules out wood?"],key:["C. It is the only one that sinks and the only one that carries heat quickly along its length, and it rings rather than denting. (5-PS1-3)","B is the dense oak. Mass decided it: 2.6 kg against 1.4 kg for the same size piece, so B is denser. (5-PS1-3)","The plastic pipe. Springing back instead of crushing or splitting rules out both woods, which dent or split instead. (5-PS1-3)"]}]},{id:22,title:"Sealed and Weighed",short:"Weigh In",parts:[{std:["5-PS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"using measurements to show that total weight is conserved through heating, cooling, and mixing",html:()=>`<p class="big">Three sealed containers from the patch were weighed, left for two weeks, and weighed again. None was opened.</p>
     <table class="bigTable"><tr><th>Sealed container</th><th>What was inside</th><th>At the start</th><th>Two weeks later</th></tr>
     <tr><td>1</td><td>a slice of pumpkin, now covered in mould</td><td>425 g</td><td>?</td></tr>
     <tr><td>2</td><td>warm water and a scoop of plant food, stirred</td><td>612 g</td><td>?</td></tr>
     <tr><td>3</td><td>crushed ice, now liquid and cool</td><td>300 g</td><td>300 g</td></tr></table>`,qs:["Container 1 is full of mould and the pumpkin slice has shrunk. What does the container weigh now?","What does container 2 weigh after the plant food has dissolved? Explain.","Someone says the mould proves matter was created, because there is now mould that was not there before. What is the better explanation?"],key:["425 g. The pumpkin's matter was rearranged into mould, water, and gas, but all of it is still sealed inside, so the total weight does not change. (5-PS1-2)","612 g. Dissolving spreads the plant food out among the water particles. Nothing left the container, so the weight is the same. (5-PS1-2)","The mould was built out of matter that was already in the pumpkin slice. Matter was rearranged, not created, which is why the total weight did not budge. (5-PS1-2)"]},{std:["5-PS1-4"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"deciding from evidence whether mixing two substances made a new substance",html:()=>`<p class="big">Three mixings tried in the potting shed.</p>
     <table class="bigTable"><tr><th>Mixing</th><th>What was seen</th></tr>
     <tr><td>crushed chalk and vinegar</td><td>fizzed steadily for a minute, and once it stopped the chalk was gone and the liquid was cloudy</td></tr>
     <tr><td>sand and dry seeds, shaken</td><td>looked mixed; a sieve separated the seeds back out whole</td></tr>
     <tr><td>a wet iron spade left out for a month</td><td>flaky orange crust where the shine used to be, and the crust will not polish off</td></tr></table>`,qs:["Which two mixings produced a new substance? Give the evidence for each.","Which one was only a mixture? What is the evidence?","A gardener dries the spade after every use and it stays shiny for years. What does that say about what is needed for the orange crust to form?"],key:["The chalk and vinegar, because a gas fizzed off and the chalk itself was used up, and the wet spade, because the orange crust is a different substance that cannot be polished back to iron. (5-PS1-4)","The sand and seeds. A sieve brought the seeds back out whole, so nothing changed, they were only mixed. (5-PS1-4)","Water is needed along with the air for rust to form. Without the water the reaction barely gets going, which is why a dried spade stays shiny. (5-PS1-4)"]}]},{id:23,title:"What Builds a Vine",short:"Plant Food",parts:[{std:["5-LS1-1"],n:3,dur:70,dir:"Read the chart. Answer out loud.",desc:"arguing from measurements that plants get their material for growth from air and water",html:()=>`<p class="big">A seed was planted in a sealed tub of weighed soil. It was watered and left in full sun. The tub let air in and out but kept every crumb of soil.</p>
     <div class="figure">${F.icon("sprout",76)}${F.icon("pumpkin",88)}${F.icon("wateringCan",76)}</div>
     <table class="bigTable"><tr><th></th><th>At planting</th><th>At harvest</th></tr>
     <tr><td>seed, then the whole vine and fruit</td><td>0.4 g</td><td>18,000 g</td></tr>
     <tr><td>dry soil in the tub</td><td>24,000 g</td><td>23,970 g</td></tr></table>`,qs:["How much did the plant gain? How much did the soil lose?","Where did almost all of the plant's new material come from?","The tub was sealed to the soil but open to the air. Explain why that detail matters to the argument."],key:["The plant gained about 18,000 g. The soil lost 30 g. (5-LS1-1)","From air and water. Carbon dioxide taken in through the leaves and water taken up by the roots are built into the plant's material using energy from sunlight. (5-LS1-1)","Because no soil could be added or lost, so the only things that went in were air, water, and sunlight. That is what lets you say the mass came from air and water rather than from soil. (5-LS1-1)"]},{std:["5-PS3-1"],n:3,dur:70,dir:"Look at the chain. Answer out loud.",desc:"using a model to trace the energy in an animal's food back to the sun",html:()=>`<p class="big">One path energy takes in the patch.</p>
     <p class="huge" style="font-size:2.2rem;margin:10px 0;text-align:center">${F.icon("sun",46)} &rarr; ${F.icon("leaf",46)} &rarr; ${F.icon("rabbit",46)} &rarr; ${F.icon("eagle",46)}</p>
     <p class="big">A rabbit eats vine leaves. A hawk eats the rabbit.</p>`,qs:["A rabbit uses energy to run, to grow, and to keep warm. Trace that energy back to where it started.","The leaves are green. What are they doing with sunlight that an animal cannot do?","Where does the energy go that the rabbit does not pass on to the hawk?"],key:["From the leaves, which captured energy from sunlight and stored it in the food they made. The rabbit got it by eating the leaves. (5-PS3-1)","Capturing it and storing it as food, built from air and water. An animal cannot make its own food, so it has to eat something that did. (5-PS3-1)","Most of it was used up while the rabbit was alive, for moving, growing, repairing its body, and keeping warm, and it left the rabbit as warmth. Only what was still stored in its body can pass on. (5-PS3-1)"]}]},{id:24,title:"The Compost Heap",short:"Matter Cycle",parts:[{std:["5-LS2-1"],n:4,dur:90,dir:"Look at the model. Answer out loud.",desc:"describing with a model how matter moves among plants, animals, decomposers, and the environment",html:()=>`<p class="big">After harvest, the spent vines, split pumpkins, and stable straw go on the compost heap. Next spring the heap is dark crumbly soil and it is spread back on the patch.</p>
     <table class="bigTable"><tr><th>From</th><th>To</th><th>How</th></tr>
     <tr><td>air and soil</td><td>pumpkin vine</td><td>the vine takes in carbon dioxide, water, and minerals</td></tr>
     <tr><td>vine and fruit</td><td>rabbits, insects, people</td><td>they eat leaves and fruit</td></tr>
     <tr><td>spent vines, split fruit, straw, waste</td><td>worms, fungi, bacteria in the heap</td><td>?</td></tr>
     <tr><td>the finished compost</td><td>?</td><td>spread back on the patch</td></tr></table>
     <div class="figure">${F.icon("leaf",70)}${F.icon("rabbit",70)}${F.icon("mushroom",70)}${F.icon("sprout",70)}</div>`,qs:["Fill in the third row. What do the worms, fungi, and bacteria do to the material?","Fill in the fourth row. Where does the finished compost send the matter next?","The heap gets warm in the middle and loses about half its volume over the winter. Where did the missing material go?","Is this model a line or a circle? Point to the arrows that decide it."],key:["They break the dead plant material and waste down into simpler substances, which is what makes the dark crumbly compost. (5-LS2-1)","Back into the soil, where the minerals in it become available to next year's plants. (5-LS2-1)","Most of it left as gas, mainly carbon dioxide and water vapour, released by the decomposers as they broke the material down. It went into the atmosphere, not out of existence. (5-LS2-1)","A circle. The matter goes from air and soil into the vine, through animals, through the decomposers in the heap, and back into the soil and the air, where it started. (5-LS2-1)"]}]},{id:25,title:"Straight Down",short:"Down",parts:[{std:["5-PS2-1"],n:3,dur:70,dir:"Answer out loud.",desc:"arguing that the gravitational force Earth exerts on objects is directed down",html:()=>`<p class="big">A pumpkin rolls off the back of a cart. To set a fence post upright, a grower hangs a weight on a string beside it and lines the post up with the string.</p>
     <div class="figure">${F.icon("pumpkin",80)}${F.icon("tractor",84)}${F.icon("key",72)}</div>`,qs:["Which way does the pumpkin travel once it leaves the cart? Which way does the weighted string hang?","Why does the hanging string tell the grower what upright means?","The patch is on a slope. A pumpkin set on the slope rolls downhill, not straight down. Does that mean the pull is sideways? Explain."],key:["Both go straight down toward the ground. (5-PS2-1)","Earth's pull on the weight is directed straight down, so the string lines up with down. A post lined up with the string is straight up and down too. (5-PS2-1)","No. The pull is still straight down. The ground is in the way and pushes back, so the only direction left for the pumpkin to move is along the slope. Take the ground away and it falls straight down. (5-PS2-1)"]},{std:["5-ESS2-1"],n:3,dur:75,dir:"Read the story. Answer out loud.",desc:"describing with an example how the geosphere, biosphere, hydrosphere, and atmosphere interact",html:()=>`<p class="big">The Earth system has four parts. The geosphere is rock and soil. The biosphere is living things. The hydrosphere is all the water. The atmosphere is air.</p>
     <p class="big">Three days of autumn rain fall on the patch. Water fills the spaces in the soil until no more will fit, then runs across the surface, carrying soil into the ditch. Vine roots sitting in waterlogged soil cannot get air and some plants wilt. Where straw was spread between the rows, the rain soaked in and little soil moved.</p>
     <div class="figure">${F.icon("rain",72)}${F.icon("drop",72)}${F.icon("sprout",72)}${F.icon("mountain",72)}</div>`,qs:["Name the two spheres that interact when rain from the air soaks into the soil.","Roots in waterlogged soil cannot get air and the plants wilt. Which three spheres are tangled together there?","The straw between the rows changed the outcome. Which sphere did the straw belong to, and which sphere did it protect?"],key:["The atmosphere and the geosphere. Water from the air enters the rock and soil. (5-ESS2-1)","The hydrosphere, because water filled the spaces, the atmosphere, because the air that normally fills those spaces was pushed out, and the biosphere, because living roots were harmed. (5-ESS2-1)","The straw is dead plant material from the biosphere. It protected the geosphere by keeping soil from being washed away, and it also helped the hydrosphere soak in rather than run off. (5-ESS2-1)"]}]},{id:26,title:"Sky Over the Patch",short:"Sky",parts:[{std:["5-ESS1-1"],n:3,dur:70,dir:"Read the chart. Answer out loud.",desc:"arguing that the sun looks brightest because of how near it is, not because it gives off the most light",html:()=>`<p class="big">Three stars, with the light each one really gives off and how far away it is.</p>
     <table class="bigTable"><tr><th>Star</th><th>Light it gives off</th><th>Distance from Earth</th></tr>
     <tr><td>the sun</td><td>1 unit</td><td>8 light-minutes</td></tr>
     <tr><td>Vega</td><td>about 40 units</td><td>25 light-years</td></tr>
     <tr><td>Polaris, the north star</td><td>over 1,000 units</td><td>about 450 light-years</td></tr></table>
     <div class="figure">${F.icon("sun",76)}${F.icon("star",76)}${F.icon("compass",76)}</div>`,qs:["Which of the three gives off the least light? Which looks brightest in the sky?","Polaris gives off more than 1,000 times the sun's light. Why is it only a modest point of light in the autumn sky?","Two stars look equally bright from the patch. Can you tell whether they give off the same amount of light? Explain."],key:["The sun gives off the least of the three. The sun also looks by far the brightest. (5-ESS1-1)","It is about 450 light-years away while the sun is 8 light-minutes away. Light spreads out as it travels, so distance makes an enormous difference to how bright something looks. (5-ESS1-1)","No. One could be a modest star close by and the other a far more powerful star much further away. You need the distance before you can work out how much light each really makes. (5-ESS1-1)"]},{std:["5-ESS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"finding patterns in graphed data about shadows, day length, and the night sky",html:()=>`<p class="big">Sunrise and sunset were written down at the patch gate on the first of each month.</p>
     <table class="bigTable"><tr><th>Month</th><th>Sunrise</th><th>Sunset</th><th>Hours of daylight</th></tr>
     <tr><td>September</td><td>6:38</td><td>19:28</td><td>12.8</td></tr>
     <tr><td>October</td><td>7:03</td><td>18:46</td><td>11.7</td></tr>
     <tr><td>November</td><td>7:32</td><td>18:09</td><td>10.6</td></tr>
     <tr><td>December</td><td>7:03</td><td>16:48</td><td>9.8</td></tr></table>`,qs:["Describe the pattern in the hours of daylight across these four months.","Sunrise got later each month until December, when it got earlier again, yet the day still got shorter. How can both be true?","On the shortest day the noon shadow of the gatepost is the longest of the year. Explain why those two go together."],key:["The days get shorter every month, from 12.8 hours down to 9.8 hours, losing about an hour a month. (5-ESS1-2)","Sunset came in much faster than sunrise moved. From November to December sunrise came half an hour earlier but sunset came more than an hour earlier, so the total daylight still fell. (5-ESS1-2)","Both come from how high the midday sun climbs. On the shortest day the sun stays lowest in the sky, so it is above the horizon for the fewest hours and it casts the longest noon shadow. (5-ESS1-2)"]}]},{id:27,title:"All of Earth's Water",short:"Water",parts:[{std:["5-ESS2-2"],n:3,dur:75,dir:"Read both charts. Answer out loud.",desc:"describing the amounts and percentages of water and fresh water in Earth's reservoirs",html:()=>`<p class="big">First, all the water on Earth.</p>
     <table class="bigTable"><tr><th>Reservoir</th><th>Share of all water</th></tr>
     <tr><td>salty ocean</td><td>about 97%</td></tr>
     <tr><td>all fresh water</td><td>about 3%</td></tr></table>
     <p class="big">Now that 3% of fresh water on its own.</p>
     <table class="bigTable"><tr><th>Where the fresh water is</th><th>Share of the fresh water</th></tr>
     <tr><td>frozen in ice caps and glaciers</td><td>about 69%</td></tr>
     <tr><td>groundwater</td><td>about 30%</td></tr>
     <tr><td>lakes, rivers, soil, and air</td><td>about 1%</td></tr></table>`,qs:["About what share of all Earth's water is fresh? Where is most of that fresh water?","Lakes and rivers are about 1% of the fresh water. Explain why that does not mean 1% of all the water on Earth.","Which chart would you use to answer the question how much of Earth's water can a farm pump out of the ground. Why?"],key:["About 3% is fresh, and about 69% of that, more than two thirds, is frozen in ice caps and glaciers. (5-ESS2-2)","The second chart is only about the 3% that is fresh. One percent of 3% is a tiny sliver of all the water, far less than 1% of the whole. (5-ESS2-2)","Both. The second chart says groundwater is about 30% of the fresh water, and the first says fresh water is about 3% of all water, so groundwater is roughly 1% of all Earth's water. You need the first chart to put the second one in scale. (5-ESS2-2)"]},{std:["5-ESS3-1"],n:3,dur:75,dir:"Read the two reports. Answer out loud.",desc:"combining information about ways communities use science to protect resources and the environment",html:()=>`<p class="big">Two farming towns tried different ways to cut waste.</p>
     <table class="bigTable"><tr><th>Town</th><th>What they did</th><th>Result after one year</th></tr>
     <tr><td>Mill End</td><td>set up a town compost yard for garden and kitchen scraps</td><td>rubbish sent to landfill down by a third, and free compost for growers</td></tr>
     <tr><td>Stone Ford</td><td>repaired leaks in the town water mains and metered each street</td><td>water pumped from the river down by a quarter with no change in use at home</td></tr></table>`,qs:["How does a compost yard reduce what goes to landfill. What does the town get out of it?","Stone Ford pumped a quarter less water without anyone using less at home. Where was that water going?","Combine the two reports into a plan for a third town that sends a lot to landfill and is also short of water."],key:["Food and garden waste is broken down by decomposers into compost instead of being buried, so less goes to landfill and the town gets soil improver it would otherwise have to buy. (5-ESS3-1)","It was leaking out of broken pipes underground before it reached anyone. Fixing the leaks saved water nobody was ever going to use. (5-ESS3-1)","Do both: a compost yard to cut what goes to landfill and put minerals back in the soil, and a leak survey with meters to stop water being lost from the pipes. The plan has to use something from each report. (5-ESS3-1)"]}]},{id:28,title:"Design a Pumpkin Cart",short:"Design It",parts:[{std:["3-5-ETS1-1"],n:3,dur:60,dir:"Listen, then answer out loud.",desc:"defining a design problem with criteria for success and constraints",read:"The patch grows giant pumpkins, some of them over 200 kilograms. Right now four adults lift each one onto a flatbed, and last year two pumpkins cracked on the way up and could not be shown at the weigh-off. The grower wants a way to move a giant pumpkin from the field to the flatbed without cracking it. One person should be able to work it, it has to roll over soft ground, and it has to be built from timber and hardware already in the barn by the end of the week.",qs:["Say the problem in one sentence.","Name three things the finished design must do to count as a success.","Name two limits the builder has to work inside."],key:["Giant pumpkins crack when they are lifted by hand, so the patch needs a way to move one onto the flatbed without damaging it. (3-5-ETS1-1)","Any three criteria from the story: moves the pumpkin without cracking it, can be worked by one person, and rolls over soft ground. (3-5-ETS1-1)","Any two constraints: only timber and hardware already in the barn, and finished by the end of the week. (3-5-ETS1-1)"]},{std:["3-5-ETS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"comparing possible solutions against the criteria and constraints",html:()=>`<p class="big">Three designs, each tried with a 200 kg test weight.</p>
     <table class="bigTable"><tr><th>Design</th><th>People needed</th><th>Rolls on soft ground?</th><th>Damage in test</th><th>Barn materials only?</th></tr>
     <tr><td>S: sling and timber ramp</td><td>1</td><td>no wheels, drags</td><td>none</td><td>yes</td></tr>
     <tr><td>T: wide-wheel barrow with a padded cradle</td><td>1</td><td>yes</td><td>none</td><td>yes</td></tr>
     <tr><td>U: hired tractor with a lifting arm</td><td>1</td><td>yes</td><td>none</td><td>no</td></tr></table>`,qs:["Which designs meet every criterion? Which of those also fits inside the limits?","Design S causes no damage and needs one person. Name the criterion it fails.","Design U does everything well. Explain why it is still not the answer here."],key:["T and U meet every criterion. Only T also fits the limits, because it is built from barn materials. (3-5-ETS1-2)","It does not roll over soft ground, it drags, which was one of the three stated needs and would be slow and hard going across a wet field. (3-5-ETS1-2)","It has to be hired, so it is not built from what is in the barn, and the limits were part of the problem. A design that ignores the constraints is not a solution to this problem. (3-5-ETS1-2)"]},{std:["3-5-ETS1-3"],n:3,dur:75,dir:"Read the test plan. Answer out loud.",desc:"planning a fair test with controlled variables and naming the failure points to improve",html:()=>`<p class="big">The builder tested two sets of wheels on the barrow to see which rolled better in a wet field.</p>
     <table class="bigTable"><tr><th></th><th>Run 1</th><th>Run 2</th></tr>
     <tr><td>wheel width</td><td>5 cm</td><td>20 cm</td></tr>
     <tr><td>load</td><td>200 kg</td><td>200 kg</td></tr>
     <tr><td>distance</td><td>30 m of the same wet row</td><td>30 m of the same wet row</td></tr>
     <tr><td>time</td><td>4 min 10 s</td><td>1 min 50 s</td></tr>
     <tr><td>what went wrong</td><td>narrow wheels cut in and sank</td><td>the cradle rocked and the load shifted on the turn</td></tr></table>`,qs:["What was held the same, and what was changed? Why does that make the comparison fair?","Suppose run 2 had also carried a lighter load. Could you still say wheel width caused the faster time? Explain.","Name one change that would fix the failure in each run."],key:["The load, the distance, and the row were all held the same and only the wheel width changed, so the difference in time can be traced to the wheels. (3-5-ETS1-3)","No. Two things would have changed, wheel width and load, so you could not tell which one made it faster. That is not a fair test. (3-5-ETS1-3)","Run 1 sank, so use the wider wheels or add a second wheel to spread the weight. Run 2 rocked, so add a strap across the cradle, deepen the cradle, or widen the frame so it does not tip on a turn. Any fix tied to the stated failure counts. (3-5-ETS1-3)"]}]},{id:29,title:"Food Before 1492",short:"Before 1492",parts:[{std:["HSS-5.1"],n:4,dur:110,dir:"Read the chart. Answer out loud.",desc:"describing pre-Columbian settlements through how people got, grew, and stored their food",html:()=>`<p class="big">How people fed themselves across four regions of North America before any European ship arrived.</p>
     <table class="bigTable"><tr><th>Region</th><th>How food was gathered</th><th>How food was kept for winter</th></tr>
     <tr><td>desert Southwest</td><td>farming corn, beans, and squash with channels that carried river water to the fields</td><td>dried corn and beans stored in sealed rooms and jars</td></tr>
     <tr><td>Pacific Northwest coast</td><td>netting and spearing salmon on the spring and autumn runs</td><td>salmon smoked and dried on racks, berries pressed into cakes</td></tr>
     <tr><td>Great Plains</td><td>hunting buffalo on foot, driving herds toward waiting hunters</td><td>meat dried and pounded with fat and berries so it kept for months</td></tr>
     <tr><td>eastern woodlands</td><td>farming the same three crops in one mound, plus hunting deer and fishing</td><td>corn dried and stored in pits lined with bark</td></tr></table>
     <div class="figure">${F.icon("corn",70)}${F.icon("fish",70)}${F.icon("herb",70)}${F.icon("box",70)}</div>`,qs:["Corn, beans, and squash were often planted together in one mound. Name one reason planting them together works better than planting them apart.","Two regions on the chart depended on an animal that moved or ran at certain times of year. Name them and say why timing mattered so much.","Every region has a way of keeping food for winter. Why was that skill as important as getting the food in the first place?","Carrying river water to a field takes planning and shared work. What does that tell you about life in the desert Southwest?"],key:["The corn stalk gives the beans something to climb, the beans put nitrogen into the soil that the corn uses, and the broad squash leaves shade the ground so weeds struggle and water stays in the soil. Partial: naming one of the three benefits is still proficient here; saying only that they grow well together, with no mechanism, is approaching. (HSS-5.1)","The Pacific Northwest, where salmon ran up the rivers only in spring and autumn, and the Great Plains, where the buffalo herds moved across the grassland. Miss the run or the herd and there was no second chance that year. Partial: the two regions named with nothing said about timing is approaching. (HSS-5.1)","Food came in bursts at harvest or on a salmon run, and nothing grew in winter. Without drying, smoking, and storing, a whole year of food would spoil within weeks and people would go hungry. Partial: saying food would spoil with nothing said about the winter gap is approaching. (HSS-5.1)","People organised large projects together, kept track of water and seasons, and built things meant to last, which takes shared decision making and knowledge passed down. Partial: saying it was hard work with no account of planning or shared decisions is approaching. (HSS-5.1)"]}]},{id:30,title:"Ships, Charts and First Contact",short:"Ships",parts:[{std:["HSS-5.2"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"explaining how early explorations of the Americas were made possible and tracing their routes",html:()=>`<p class="big">Long ocean voyages became possible because of tools and ship designs that spread through Europe in the 1400s.</p>
     <table class="bigTable"><tr><th>Tool or design</th><th>What it let a sailor do</th></tr>
     <tr><td>the caravel, a small ship with triangular sails</td><td>sail closer to the wind instead of only with it</td></tr>
     <tr><td>the magnetic compass</td><td>hold a direction out of sight of land, even under cloud</td></tr>
     <tr><td>the astrolabe and later the quadrant</td><td>measure the height of the sun or a star to work out how far north or south you were</td></tr>
     <tr><td>printed charts and logbooks</td><td>record a route so the next voyage could repeat or improve it</td></tr></table>
     <div class="figure">${F.icon("sailboat",76)}${F.icon("compass",76)}${F.icon("books",76)}</div>`,qs:["Which tool told a sailor which way the ship was pointing. Which told them how far north or south they were?","Why would a ship that can sail closer to the wind be able to make a voyage that an older ship could not?","Explain why written charts and logbooks mattered as much as the compass.","Columbus sailed west in 1492 and Cartier went up the Saint Lawrence River in 1534. Which voyage could use charts drawn from the other, and why?"],key:["The compass gave the direction. The astrolabe or quadrant gave the latitude, how far north or south. Partial: one of the two tools matched is approaching. (HSS-5.2)","An older ship had to wait for a following wind and could be stuck or blown off course for weeks. A caravel could make progress against a crosswind, so the voyage was quicker and the ship could get home again. Partial: saying the newer ship was better with nothing said about waiting for a following wind is approaching. (HSS-5.2)","A compass helps one sailor on one voyage. A written chart lets everyone who comes after follow a route that is known to work, so each voyage builds on the last instead of starting over. Partial: saying charts were useful with nothing said about later voyages building on earlier ones is approaching. (HSS-5.2)","Cartier in 1534 could use charts from the earlier voyages, including Columbus in 1492 and Cabot in 1497, because they came first. Knowledge travelled forward in time, not backward. Partial: the right voyage named with no reason is approaching. (HSS-5.2)"]},{std:["HSS-5.3"],n:4,dur:100,dir:"Read the account. Answer out loud.",desc:"describing cooperation and then conflict between an American Indian nation and a new colony",html:()=>`<p class="big">In 1620 a small English colony was planted at Plymouth, on land of the Wampanoag nation. The Wampanoag had already lost many people to an illness carried by earlier European visitors.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1620 to 1621</td><td>about half the colonists died in the first winter; Wampanoag people showed them which crops grew there and how to fish the local waters</td></tr>
     <tr><td>1621</td><td>the colony and the Wampanoag leader Massasoit agreed to peace and mutual defence, and shared a harvest meal that autumn</td></tr>
     <tr><td>1640s to 1660s</td><td>more English settlers arrived, fenced more land, and pressed the Wampanoag to sell; the agreement held but strained</td></tr>
     <tr><td>1675</td><td>war broke out across the region after years of broken agreements and lost land</td></tr></table>`,qs:["Name two ways the Wampanoag helped the colony survive its first year.","The 1621 agreement was useful to both sides. What did each side get from it?","The chart covers about fifty-five years. Describe how the relationship changed over that time, and name the main cause.","An interpreter named Tisquantum, often called Squanto, had been taken to Europe and came back speaking English. Why would a person like that matter so much to both sides?"],key:["They showed the colonists which crops would grow in that soil and how to fish the local waters. Accept trade for food as well. Partial: one way named is approaching. (HSS-5.3)","The colonists got food, knowledge, and safety while they were few and weak. The Wampanoag got a trading partner and an ally at a time when illness had reduced their numbers and rival nations were stronger. Partial: one side's gain named is approaching. (HSS-5.3)","It began as cooperation that both sides needed, strained as more settlers arrived and took more land, and ended in war. The main cause was the steady loss of Wampanoag land and agreements the settlers did not keep. Partial: the change described with no main cause named is approaching. (HSS-5.3)","Neither side could speak the other's language, so an interpreter decided what each side understood the other to be saying. That gave him real influence, and it also meant misunderstandings in an agreement could last for years. Partial: saying he could translate with nothing said about the influence or the risk of misunderstanding is approaching. (HSS-5.3)"]}]},{id:31,title:"Self Government and Protest",short:"Protest",parts:[{std:["HSS-5.4"],n:4,dur:145,dir:"Read the chart. Answer out loud.",desc:"describing colonial self-government and who was allowed to take part in it",html:()=>`<p class="big">Each colony ran much of its own business through an assembly, but who could take part was narrow.</p>
     <table class="bigTable"><tr><th>Body</th><th>What it did</th><th>Who chose it</th></tr>
     <tr><td>colonial assembly</td><td>passed local laws, set local taxes, paid the governor's salary</td><td>elected by free men who owned a certain amount of property</td></tr>
     <tr><td>royal governor</td><td>represented the king, could reject laws the assembly passed</td><td>appointed in London</td></tr>
     <tr><td>New England town meeting</td><td>decided local matters such as roads, schools, and the common land</td><td>open to property-owning men of the town</td></tr>
     <tr><td>established church, in Virginia and several other colonies</td><td>collected a parish tax from everyone in the parish, kept the records of births and marriages, and ran poor relief</td><td>its ministers were appointed, not elected, and in several colonies only a Protestant could hold public office</td></tr></table>
     <p class="big">Women, enslaved people, most free Black people, and men who owned no property could not vote, which left most adults out.</p>`,qs:["Name one power the colonial assembly held and one power the established church held in a colony that had one.","Assemblies often paid the governor's salary. Why would that give an assembly leverage over a governor appointed in London?","Who could vote for an assembly, and roughly what share of adults does that leave out?","Colonists later said they were defending rights they already had. Which institution on the chart were they thinking of, and why?"],key:["The assembly passed local laws and set local taxes. The established church collected a parish tax from everyone in the parish, kept the records of births and marriages, and ran poor relief. Accept as well that its ministers were appointed rather than elected, which is the opposite of how an assembly was chosen. Partial: one of the two institutions' powers named is approaching. (HSS-5.4)","A governor who refused what the assembly wanted might find his pay delayed or reduced, so he had a strong reason to work with them even though London had appointed him. Partial: noting the assembly paid him with no account of the leverage is approaching. (HSS-5.4)","Only free men who owned enough property. Women, enslaved people, most free Black people, and men without property were all excluded, which left most adults with no vote. Credit as well a student who adds that in several colonies only a Protestant could hold office, which narrowed it further. Partial: naming the property requirement with no account of who was left out is approaching. (HSS-5.4)","The colonial assembly and the town meeting. They had been deciding their own taxes and local laws for generations, so a tax passed in London felt like a right being taken away rather than a new rule. Partial: the institution named with no reason is approaching. (HSS-5.4)"]},{std:["HSS-5.5"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"explaining how colonial protest spread and why it became a cause of the Revolution",html:()=>`<p class="big">Colonists did more than complain. They organised.</p>
     <table class="bigTable"><tr><th>Action</th><th>How it worked</th></tr>
     <tr><td>boycott</td><td>colonists agreed to stop buying British cloth, tea, and other goods</td></tr>
     <tr><td>homespun cloth</td><td>women spun and wove at home so families did not need imported cloth</td></tr>
     <tr><td>committees of correspondence</td><td>colonies wrote to each other to share news and agree on a response</td></tr>
     <tr><td>First Continental Congress, 1774</td><td>delegates from twelve colonies met and agreed on a joint boycott</td></tr></table>`,qs:["How does a boycott put pressure on a government that is far away?","Why was spinning cloth at home a political act and not only housework?","Before the committees of correspondence, each colony dealt with London on its own. Why did writing to each other change what was possible?","Why would a joint boycott agreed by twelve colonies worry Parliament more than a protest in one city?"],key:["British merchants lose money when colonists stop buying, and those merchants have votes and influence in Parliament, so they press the government to change the law. Partial: saying the government loses money with nothing said about merchants pressing Parliament is approaching. (HSS-5.5)","Imported cloth was one of the main things being boycotted, so making cloth at home was what made the boycott possible. It turned a household job into a way of taking part in the protest. Partial: saying it saved money with no link to the boycott is approaching. (HSS-5.5)","Shared news meant colonists learned quickly what had happened elsewhere and could agree on one answer. Thirteen separate complaints are easy to ignore; one coordinated response is not. Partial: saying they could share news with nothing said about acting as one is approaching. (HSS-5.5)","Because it showed the colonies could act as one. A single city can be punished or waited out, but a boycott across twelve colonies threatened British trade as a whole and suggested a united opposition. Partial: saying it was bigger with nothing said about the colonies acting together is approaching. (HSS-5.5)"]},{std:["HSS-5.6"],n:4,dur:110,dir:"Read the extract and the notes. Answer out loud.",desc:"explaining what the Declaration of Independence claimed and what followed from it",html:()=>`<p class="big">The Declaration of Independence was approved on 4 July 1776, more than a year after the fighting began.</p>
     <table class="bigTable"><tr><th>Part of the document</th><th>What it says, in plain words</th></tr>
     <tr><td>the opening idea</td><td>all men are created equal and have rights that cannot be taken away, among them life, liberty, and the pursuit of happiness</td></tr>
     <tr><td>where government comes from</td><td>governments get their power from the consent of the people they govern</td></tr>
     <tr><td>the long list</td><td>a list of specific actions by the king that the colonists said broke that trust</td></tr>
     <tr><td>the conclusion</td><td>the thirteen colonies are free and independent states</td></tr></table>`,qs:["Why did the writers include a long list of the king's actions instead of only stating the idea?","What does it mean to say a government gets its power from the consent of the people?","The Declaration says all men are created equal, yet the man who drafted it enslaved people, and slavery continued in the new country. How do you hold both of those facts at once?","The war had been going on since 1775. What changed once the Declaration was approved?"],key:["The list was the evidence. Stating a principle alone could be argued with, but a list of specific actions was meant to show readers at home and in Europe that the colonists had real grounds and were not simply rebelling. Partial: saying the list showed what the king did with nothing said about who they were trying to convince is approaching. (HSS-5.6)","That people agree to be governed, and a government that loses their agreement loses its right to rule. Power comes up from the people rather than down from a king. Partial: saying the people choose the government with nothing said about losing the right to rule is approaching. (HSS-5.6)","Both are true and they sit badly together. The words set out a standard the country did not meet at the time, and people who were left out, including enslaved and free Black Americans and women, used those same words for generations afterward to argue that the promise should be kept. Partial: naming the contradiction with nothing said about how the words were later used is approaching. (HSS-5.6)","The aim changed from forcing Britain to change its laws to becoming a separate country, which made a negotiated return impossible and made foreign alliances such as the one with France possible. Partial: saying it made things official with no account of the change in aim is approaching. (HSS-5.6)"]}]},{id:32,title:"Branches and Routes West",short:"New Nation",parts:[{std:["HSS-5.7"],n:4,dur:110,dir:"Read the chart. Answer out loud.",desc:"describing how the Constitution divides power and checks each branch",html:()=>`<p class="big">The Constitution gives each branch a way to check the others.</p>
     <table class="bigTable"><tr><th>Branch</th><th>Its job</th><th>A check it holds</th></tr>
     <tr><td>legislative, which is Congress</td><td>makes the laws</td><td>can override a veto, controls spending, approves appointments</td></tr>
     <tr><td>executive, which is the president</td><td>carries out the laws</td><td>can veto a bill Congress has passed</td></tr>
     <tr><td>judicial, which is the courts</td><td>decides what the laws mean</td><td>can rule that a law conflicts with the Constitution</td></tr></table>`,qs:["Congress passes a bill and the president vetoes it. Is the bill finished? Explain.","Why would the writers want no single branch able to act alone?","Give one example of a check the president holds and one a court holds.","The delegates had just fought a war against a king. How does the chart show what they learned from that?"],key:["Not necessarily. Congress can override a veto if enough members vote for the bill again, so the two branches each hold part of the decision. Partial: saying the bill is finished is not yet right; saying it is not finished with no account of the override is approaching. (HSS-5.7)","They had seen power used without limits and wanted no person or group able to make, enforce, and judge the rules on their own. Each branch needing the others slows down any attempt to seize control. Partial: saying it is fairer with no account of one group making, enforcing and judging is approaching. (HSS-5.7)","The president can veto a bill. A court can rule that a law conflicts with the Constitution. Partial: one of the two checks named is approaching. (HSS-5.7)","Every power on the chart is split and watched by another branch. Rather than replacing one ruler with another, they divided the job three ways so no one could rule alone. Partial: saying they did not want a king with nothing from the chart is approaching. (HSS-5.7)"]},{std:["HSS-5.8"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"comparing transport systems and explaining how they shaped where people settled",html:()=>`<p class="big">Moving a tonne of wheat from the middle of the country to a port on the coast, around 1820 and around 1850.</p>
     <table class="bigTable"><tr><th>Way of moving it</th><th>Rough time</th><th>Rough cost</th><th>Goes where</th></tr>
     <tr><td>wagon on a dirt road</td><td>weeks</td><td>very high</td><td>anywhere, slowly</td></tr>
     <tr><td>flatboat down a river</td><td>days, one way only</td><td>low</td><td>only downstream</td></tr>
     <tr><td>steamboat</td><td>days, both ways</td><td>low</td><td>along navigable rivers</td></tr>
     <tr><td>canal barge</td><td>days</td><td>very low</td><td>only where a canal was dug</td></tr>
     <tr><td>railroad</td><td>a day or two</td><td>low</td><td>wherever track was laid, in any season</td></tr></table>
     <div class="figure">${F.icon("canoe",70)}${F.icon("truck",70)}${F.icon("bridge",70)}</div>`,qs:["A flatboat was cheap. Name its biggest drawback and say what fixed it.","Canals were very cheap to use. Why did they not simply replace everything else?","The railroad column says in any season. Why did that matter so much compared with rivers and canals?","Pick one of these systems and explain how it decided where towns grew."],key:["It only went downstream, so a boat could not bring goods or itself back up. The steamboat fixed that by moving under its own power both ways. Partial: naming the drawback with nothing said about what fixed it is approaching. (HSS-5.8)","A canal only goes where one has been dug, which costs an enormous amount and is only possible on fairly level ground, so most places could never have one. Partial: saying canals were expensive with nothing said about level ground is approaching. (HSS-5.8)","Rivers and canals froze in winter and ran low or flooded at other times, which stopped traffic for weeks. A railroad kept running, so trade and travel no longer stopped for the season. Partial: naming the freeze with nothing said about trade stopping for weeks is approaching. (HSS-5.8)","Any supported answer. Towns grew where a canal met a lake or a river, at the ends of a canal, at river landings where steamboats stopped, and later at railroad junctions and water stops, because that is where goods changed hands and work was to be had. Partial: a system named with no place where towns grew, or a place with no reason, is approaching. (HSS-5.8)"]},{std:["HSS-5.9"],n:5,dur:90,dir:"Answer out loud. A map is fine to look at.",desc:"locating southern states and naming their capitals",html:()=>`<div class="figure">${F.icon("map",96)}${F.icon("globe",96)}</div>
     <p class="big">Questions about the South and about capitals in general.</p>`,qs:["Name four states that touch the Gulf of Mexico.","What is the capital of Georgia, and what is the capital of Florida?","Which state is the farthest south of the mainland states. Which two states does the Mississippi River separate at its mouth?","Virginia's capital was also the capital of the Confederacy during the Civil War. Name it.","How many states are there in all. Then name the two that are not joined to the others by land."],key:["Any four of Texas, Louisiana, Mississippi, Alabama, and Florida. Partial: two or three of the four named is approaching. (HSS-5.9)","Atlanta, Georgia and Tallahassee, Florida. Note if the student names Miami or Orlando, which is the usual slip. Partial: one of the two capitals right is approaching. (HSS-5.9)","Florida reaches farthest south on the mainland. At its mouth the Mississippi River runs through Louisiana; further north it separates Louisiana and Mississippi. Accept Louisiana and Mississippi. Partial: one of the two answered is approaching. (HSS-5.9)","Richmond (HSS-5.9)","50 states. Alaska and Hawaii are not joined to the others by land. Partial: the count right with one of the two states named is approaching. (HSS-5.9)"]}]}];const WC=STORY.split(/\s+/).filter(Boolean).length;const readPart=STOPS[0].parts[0];readPart.n=WC;readPart.key[0]=readPart.key[0].replace("__WC__",WC);readPart.desc=`a ${WC}-word grade-level story read aloud`;const LEVELUPS={4:{id:"L4",title:"Level Up: Power Pumpkins",std:["6.EE.A.1"],needs:["5.OA.A.1"],n:3,dir:"Solve on your paper. Then tell your teacher your answers.",html:()=>`<ol class="qlist"><li>6<sup>2</sup> = ?</li><li>2<sup>4</sup> + 5 = ?</li><li>Write 10 × 10 × 10 with an exponent. Then tell its value.</li></ol>`,key:["36, from 6 × 6. (6.EE.A.1)","21. 2 × 2 × 2 × 2 is 16, and 16 + 5 = 21. (6.EE.A.1)","10³, which is 1,000. (6.EE.A.1)"]},7:{id:"L7",title:"Level Up: Word Choice",std:["RL.6.4"],needs:["RL.5.4"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<ol class="qlist"><li>The author wrote, “The tractor coughed twice.” Why do you think the author chose the word coughed? What picture or feeling does that word give you?</li><li>Near the end, the breeze “slid over the field like a sigh.” What feeling do the words sigh and proud give to the ending of the story?</li></ol>${F.passage(WAGON,WAGON_TITLE,true)}`,key:["Coughed makes the tractor sound old, tired, or slow to start, almost like a person. It fits the worn-out feeling at the end of a long work day. (RL.6.4, connotation and the effect of a word choice)","A calm, restful, satisfied feeling. A sigh is what people do when hard work is over. The mood moves from tired to peaceful and proud. (RL.6.4, effect of word choice on tone)"]},11:{id:"L11",title:"Level Up: Pronoun Patch",std:["L.6.1"],needs:["L.5.1"],n:3,dir:"Say each sentence out loud the right way.",html:()=>`<ol class="qlist"><li>Fix it: “If a visitor wants a wagon ride, you should line up at the barn.”</li><li>Add one word to show that no one helped: “We built the scarecrow ____.”</li><li>Pick the right word: “(She, Her) and Rohan grew the tallest sunflower.”</li></ol>`,key:["If a visitor wants a wagon ride, he or she should line up at the barn. Also correct: If visitors want a wagon ride, they should line up at the barn. Or: If you want a wagon ride, you should line up at the barn. (L.6.1, fixing a shift in pronoun person)","We built the scarecrow ourselves. (L.6.1, intensive pronoun)","She and Rohan grew the tallest sunflower. (L.6.1, subject pronoun)"]},13:{id:"L13",title:"Level Up: Source Checker",std:["W.6.8"],needs:["W.5.8"],n:2,dir:"Answer out loud.",html:()=>`${sourcesHtml()}<div class="texts" style="margin-top:10px"><article><h3>Source 3</h3><p class="small" style="margin:0 0 6px">A comment posted under a video by someone called PumpkinFan77</p><p>Giant pumpkins get big because growers play music for them every night. Trust me.</p></article></div><ol class="qlist"><li>Which of the three sources would you trust the least? Give two reasons.</li><li>You want to use the last sentence of Source 1 in a report, word for word. Tell what you must do so that readers know the words are not yours.</li></ol>`,key:["Source 3. Reasons, such as: we do not know who the writer is or what the writer knows, it is only a comment and not a book or an article, it gives no proof (“Trust me”), and the other two sources do not say it. Two reasons are needed. (W.6.8, judges the credibility of each source)","Put the sentence in quotation marks and name the source: the title, Giants of the Garden, and the author, Rosa Castillo. (W.6.8, quotes without plagiarizing and gives basic source information)"]}};const PASSAGE_STD=["RL.5.1","RL.5.4","RI.5.1","RI.5.9","W.5.8","RL.6.4","W.6.8"];const MULT_N=12;let multSel=[0,0];function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function pvChart(){const head=["Thousands","Hundreds","Tens","Ones",".","Tenths","Hundredths","Thousandths"],vals=["1,000","100","10","1",".","0.1","0.01","0.001"],fr=["","","","",".","1/10","1/100","1/1000"];const cell=(c,i,tag2,extra)=>{const dec=i>=4;const st=`padding:${tag2==="th"?"8px 4px":"10px 4px"};text-align:center;${i===4?"width:20px;font-size:1.4rem;font-weight:700;":""}${dec&&i>4?"background:var(--sea-soft);":""}${extra||""}`;return`<${tag2} style="${st}">${c}</${tag2}>`};const row=(arr,tag2,extra)=>`<tr>${arr.map((c,i)=>cell(c,i,tag2,extra)).join("")}</tr>`;return`<div class="tool-scroll"><table class="chart" style="width:100%;font-size:.95rem">${row(head,"th","font-size:.74rem;white-space:nowrap;padding-left:1px;padding-right:1px;")}${row(vals,"td","font-weight:700;")}${row(fr,"td","font-size:.85rem;")}${row(["","","","",".","","",""],"td","height:54px;font-size:1.8rem;font-weight:700;")}</table></div><p class="small">The bottom row is for digits. Each place to the left is worth 10 times as much. Each place to the right is worth 1/10 as much. The last place, <b>thousandths</b>, is the third one after the point.</p>`}function strips(){const dens=[1,2,3,4,5,6,8,12],W=600,h=36;let s=`<svg viewBox="0 0 ${W+8} ${dens.length*(h+6)+4}" width="100%" style="max-width:640px" role="img" aria-label="Fraction strips for halves, thirds, fourths, fifths, sixths, eighths, and twelfths">`;dens.forEach((d,r)=>{for(let k=0;k<d;k++){const x=4+k*W/d,y=2+r*(h+6);s+=`<rect x="${x}" y="${y}" width="${W/d}" height="${h}" fill="${r%2?"var(--sea-soft)":"var(--surface)"}" stroke="var(--ink)" stroke-width="1.5"/><text x="${x+W/d/2}" y="${y+h/2}" text-anchor="middle" dominant-baseline="central" font-size="${d>8?14:17}" fill="var(--ink)">${d===1?"1":"1/"+d}</text>`}});return s+"</svg>"}const frames=list=>`<ul class="starters">${list.map(x=>`<li>${x}</li>`).join("")}</ul>`;function sentHtml(st){const has=c=>st&&st.std&&st.std.includes(c);if(has("W.5.1"))return frames(["I think the top ribbon should go to ____.","One reason is ____. For example, ____.","Another reason is ____.","That is why ____."]);if(has("W.5.3"))return frames(["It all started when ____.","At first, ____.","Just then, ____.","“____,” I said.","In the end, ____."]);if(has("W.5.2"))return frames(["Pumpkins are ____.","One interesting fact is ____.","Another fact is ____.","For example, ____.","Now you know ____."]);if(has("SL.5.4"))return frames(["Today I will tell you how ____.","First, ____. Next, ____.","After that, ____.","Finally, ____.","That is how ____."]);if(has("W.5.8"))return frames(["Note: ____ (Source ____)","My sources: 1. ____ by ____. 2. ____ by ____.","Growers get a pumpkin to grow big by ____ and ____."]);return frames(["The story says, “____.”","I know ____ because the story says, “____.”","The words “____” show that ____."])}const TOOLS={mult:{name:"Multiplication chart",std:["5.NF.B.3","5.NF.B.4","5.NF.A.1","5.NF.A.2","5.MD.C.5","5.OA.A.1","6.EE.A.1"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const row=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===row&&multSel[1]===k?[0,0]:[row,k];r()})},pv:{name:"Place value chart to thousandths",std:["5.NBT.A.1","5.NBT.A.3"],html:pvChart},strips:{name:"Fraction strips",std:["5.NF.B.3","5.NF.B.4","5.NF.A.1","5.NF.A.2"],html:strips},formula:{name:"Fraction formula card",std:["5.NF.B.3","5.NF.B.4"],html:()=>`<ul class="starters"><li>A fraction is a division problem: a/b = a ÷ b.</li><li>Fraction times fraction: multiply the tops, then multiply the bottoms.</li><li>A whole number can be written over 1: 4 = 4/1.</li><li>“Of” means multiply: 1/2 of 6 is 1/2 × 6.</li></ul>`},ops:{name:"Order of operations card",std:["5.OA.A.1"],html:()=>`<ol class="starters"><li>Work from the inside out: ( ) first, then [ ], then { }.</li><li>Then multiply and divide, left to right.</li><li>Then add and subtract, left to right.</li></ol>`},sent:{name:"Sentence frames",std:["W.5.1","W.5.2","W.5.3","W.5.8","SL.5.4","RL.5.1"],html:sentHtml},figs:{name:"Simile and metaphor card",std:["RL.5.4"],html:()=>`<ul class="starters"><li>Simile: compares two things with like or as. “Her smile was like sunshine.”</li><li>Metaphor: says one thing is another thing. “The classroom was a zoo.”</li><li>Ask: What two things are compared? How are they alike?</li></ul>`}};const SUP_CAVEATS=[{t:"mult",std:["5.NF.B.3","5.NF.B.4","5.OA.A.1","6.EE.A.1"],msg:"The multiplication chart gives the products and quotients. Rate on whether the student sets up the problem and explains it."},{t:"pv",std:["5.NBT.A.1"],msg:"The place value chart states the 10 times and 1/10 rule, which is what 5.NBT.A.1 checks. Count this stop as supported, not independent."},{t:"pv",std:["5.NBT.A.3"],msg:"The place value chart names each decimal place, so count reading and writing the decimals as supported."},{t:"strips",std:["5.NF.B.3","5.NF.B.4"],msg:"With fraction strips the student can see the size of each share or part. Rate on whether the student can write the equation and explain it."},{t:"strips",std:["5.NF.A.1","5.NF.A.2"],msg:"Lining up fifths against tenths on the strips finds the common denominator for the student. Note that the renaming step was supported."},{t:"formula",std:["5.NF.B.3","5.NF.B.4"],msg:"The formula card gives the rules for fractions as division and for multiplying fractions. Count this stop as supported, not independent."},{t:"ops",std:["5.OA.A.1"],msg:"The card gives the order to work in. Count this stop as supported, not independent."},{t:"sent",std:["W.5.1","W.5.2","W.5.3"],msg:"Sentence frames supply the opening, the linking or time words, and the closing, so count those checks as supported, not independent."},{t:"sent",std:["SL.5.4"],msg:"Sentence frames supply the order words and the closing, so count those checks as supported."},{t:"sent",std:["W.5.8"],msg:"The frames show how to label a note and list a source, so count the list of sources as supported."},{t:"sent",std:["RL.5.1"],msg:"The frames remind the student to quote. Rate on the accuracy of the quote."},{t:"figs",std:["RL.5.4"],msg:"The card tells what a simile and a metaphor are, so count the simile or metaphor question as supported."},{t:"passage",std:["RL.5.1","RL.5.4","RL.6.4","RI.5.1","RI.5.9"],msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"passage",std:["W.5.8","W.6.8"],msg:"If the sources were read to the student, the notes still count for W.5.8, but write down that the sources were read aloud."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
